function TokenBucket(options) {
  if (options === undefined || options === null) {
    throw new RangeError("Options object is required");
  }

  const { capacity, refillPerSecond, now } = options;

  if (!isFinite(capacity) || capacity <= 0 || isNaN(capacity)) {
    throw new RangeError("capacity must be a finite positive number");
  }

  if (typeof refillPerSecond !== 'number' || !isFinite(refillPerSecond) || refillPerSecond < 0 || isNaN(refillPerSecond)) {
    throw new RangeError("refillPerSecond must be a non-negative finite number");
  }

  const _now = now || Date.now;
  const _capacity = capacity;
  const _refillPerSecond = refillPerSecond;

  let _tokens = _capacity;
  let _lastUpdate = _now();

  function _refill() {
    const now = _now();
    const delta = now - _lastUpdate;
    if (delta <= 0) {
      return;
    }

    const seconds = delta / 1000;
    const refill = seconds * _refillPerSecond;

    _tokens = Math.min(_capacity, _tokens + refill);
    _lastUpdate = now;
  }

  function tryTake(n) {
    if (typeof n !== 'number' || !isFinite(n) || n < 0 || isNaN(n)) {
      throw new RangeError("n must be a finite positive number");
    }

    _refill();
    if (_tokens >= n) {
      _tokens -= n;
      return true;
    }
    return false;
  }

  function available() {
    _refill();
    return _tokens;
  }

  function msUntil(n) {
    if (typeof n !== 'number' || !isFinite(n) || n < 0 || isNaN(n)) {
      throw new RangeError("n must be a finite positive number");
    }

    _refill();

    if (n > _capacity || _refillPerSecond === 0) {
      if (n > _tokens) {
        return Infinity;
      }
      return 0;
    }

    if (_tokens >= n) {
      return 0;
    }

    const needed = n - _tokens;
    const seconds = needed / _refillPerSecond;
    return Math.ceil(seconds * 1000);
  }

  return {
    tryTake,
    available,
    msUntil
  };
}

module.exports = { TokenBucket };

