const { TokenBucket } = require('./kova.js');

// Test 1: Temel oluşturma ve dolum
console.log('Test 1: Temel oluşturma');
try {
  const now = () => 1000;
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });
  console.log('  available():', bucket.available()); // 10 (dolu)
  console.log('  tryTake(5):', bucket.tryTake(5)); // true
  console.log('  available() after take:', bucket.available()); // 5
  console.log('  msUntil(3):', bucket.msUntil(3)); // ~1500ms
} catch (e) { console.error('FAIL:', e.message); }

// Test 2: Capacity sınır test
console.log('Test 2: Capacity sınırı');
try {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: () => 1000 });
  bucket.tryTake(10);
  console.log('  available():', bucket.available()); // 0
  const before = () => 1000;
  const after = () => 1000;
  console.log('  msUntil(5) when full:', bucket.msUntil(5)); // ~1000ms
} catch (e) { console.error('FAIL:', e.message); }

// Test 3: tryTake başarısız
console.log('Test 3: tryTake başarısız');
try {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => 1000 });
  console.log('  tryTake(15):', bucket.tryTake(15)); // false, tokens değişmez
  console.log('  available() after failed take:', bucket.available()); // 10
} catch (e) { console.error('FAIL:', e.message); }

// Test 4: msUntil Infinity
console.log('Test 4: msUntil Infinity');
try {
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 1000 });
  console.log('  msUntil(10):', bucket.msUntil(10)); // Infinity (capacity daha küçük)
  const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now: () => 1000 });
  bucket2.tryTake(5);
  console.log('  msUntil(3) with 0 refill:', bucket2.msUntil(3)); // 0 (yeterli)
  console.log('  msUntil(10) with 0 refill:', bucket2.msUntil(10)); // Infinity (yetersiz)
} catch (e) { console.error('FAIL:', e.message); }

// Test 5: Kesikli dolum (fractional refill)
console.log('Test 5: Kesikli dolum');
try {
  let clock = 1000;
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 1.5, now: () => { clock += 500; return clock; } });
  console.log('  initial:', bucket.available()); // 10
  console.log('  after 500ms:', bucket.available()); // 10.75
} catch (e) { console.error('FAIL:', e.message); }

// Test 6: Hata durumları
console.log('Test 6: Hata durumları');
try {
  new TokenBucket({ capacity: -1, refillPerSecond: 1 });
  console.error('FAIL: negative capacity');
} catch (e) { console.log('  negative capacity: OK, throws:', e.message); }

try {
  new TokenBucket({ capacity: 10, refillPerSecond: 'slow' });
  console.error('FAIL: string refillPerSecond');
} catch (e) { console.log('  string refillPerSecond: OK, throws:', e.message); }

try {
  new TokenBucket({ capacity: 10, refillPerSecond: 0, now: () => 1000 });
  new TokenBucket({ capacity: 10, refillPerSecond: NaN, now: () => 1000 });
  console.error('FAIL: NaN refillPerSecond');
} catch (e) { console.log('  NaN refillPerSecond: OK, throws:', e.message); }

try {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => 1000 });
  bucket.tryTake(-1);
  console.error('FAIL: negative n in tryTake');
} catch (e) { console.log('  negative n in tryTake: OK, throws:', e.message); }

console.log('\\nTestler tamamlandı.');
